        rg_BuZhi = ExecuteCDPAndSyncWait (_CT2 (_T ("_dbg_land")), _CT2 (_T ("Runtime.evaluate")), _CT2 (_T ("{\"expression\":\"setTimeout(function(){var _mcpPauseLanding=1;},30)\",\"returnByValue\":true}")), 4000);
