    MenuAliasCandidates.data ().Add4 (NUM_CHARS_OF_TEXT ("S"), _T ("paste"));
    MenuAliasCandidates.data ().Add4 (NUM_CHARS_OF_TEXT ("S"), _T ("delete"));
